p='/home/claude/site/index.html';h=open(p,encoding='utf-8').read()
def rep(a,b):
    global h
    assert h.count(a)==1,(h.count(a),a[:90]);h=h.replace(a,b)
# renders keep their piece and carry the editor's settings
rep("PBC.render({seed:t.seed,genre:t.style,blend:t.blend,source:'library',faith:t.faith??s.src/100,avoid:s.usedPieces,L,offset:null,A,ctx}",
    "PBC.render({seed:t.seed,genre:t.style,blend:t.blend,source:'library',faith:t.faith??s.src/100,avoid:s.usedPieces,L,offset:null,A,ctx,piece:t.piece||undefined,ch:t.ch||null,song:t.song||null}")
rep("t.file=new File([wav(r.buffer)],t.name+'.wav',{type:'audio/wav'});","t.piece=r.piece||t.piece;t.chan=r.meta.chan;t.edit=null;t.songDef=r.meta.song;t.songEdit=null;t.file=new File([wav(r.buffer)],t.name+'.wav',{type:'audio/wav'});")
rep("head.append(pb,name,rr,heart,dl);","const ie=document.createElement('button');ie.className='pill'+(t.showEd?' on':'');ie.textContent='Instruments & effects';ie.disabled=!t.chan;ie.onclick=()=>{t.showEd=!t.showEd;render()};head.append(pb,name,rr,ie,heart,dl);")
rep("row.append(head,info,stage);","row.append(head,info,stage);if(t.showEd&&t.chan)row.append(fxEditor(t));")
JS=r"""
const FXF=[['gain','Amplitude',-48,12,.5,v=>(v>0?'+':'')+v+' dB'],['oct','Octave shift',-2,2,1,v=>v==0?'As written':(v>0?'+':'')+v+(Math.abs(v)==1?' octave':' octaves')],['pan','Stereo placement',-1,1,.05,v=>Math.abs(v)<.03?'Center':(Math.round(Math.abs(v)*100)+'% '+(v<0?'L':'R'))],['sep','Stereo separation',0,2,.05,v=>Math.round(v*100)+'%'],['verb','Reverb amount',0,1,.01,v=>Math.round(v*100)+'%'],['space','Reverb space'],['dly','Delay send',0,1,.01,v=>Math.round(v*100)+'%'],['low','Low EQ · 180 Hz',-18,18,.5,v=>v+' dB'],['mid','Mid EQ',-18,18,.5,v=>v+' dB'],['midF','Mid frequency',150,8000,50,v=>v+' Hz'],['high','High EQ · 6 kHz',-18,18,.5,v=>v+' dB'],['hpf','High-pass filter',20,2000,10,v=>v+' Hz'],['lpf','Low-pass filter',2000,20000,100,v=>v+' Hz'],['sat','Saturation (tape/tube warmth)',0,1,.01,v=>Math.round(v*100)+'%'],['comp','Compression',0,1,.01,v=>Math.round(v*100)+'%'],['chorus','Chorus / ensemble',0,1,.01,v=>Math.round(v*100)+'%'],['jit','Timing looseness',0,3,.05,v=>Math.round(v*100)+'%'],['lean','Push · lay back',-30,30,1,v=>v==0?'on the grid':(v>0?v+' ms behind':(-v)+' ms ahead')],['dyn','Dynamics range',0,2,.05,v=>Math.round(v*100)+'%'],['track','Velocity → brightness',0,2,.05,v=>Math.round(v*100)+'%'],['strum','Chord roll / strum',0,3,.05,v=>Math.round(v*100)+'%'],['len','Note length',.5,1.6,.02,v=>Math.round(v*100)+'%'],['glide','Glide / portamento',0,3,.05,v=>Math.round(v*100)+'%'],['vib','Vibrato depth',0,3,.05,v=>Math.round(v*100)+'%'],['vibDelay','Vibrato delay',0,1.5,.05,v=>v.toFixed(2)+' s']];
const ROLEN={lead:'Lead',keys:'Keys',pulse:'Pulse',riff:'Riff',pad:'Pad',pad2:'Pad 2',bass:'Bass',sub:'Sub bass',color:'Color',counter:'Counter',dbl:'Double',drums:'Drums'};
let insOpts=null;const insList=()=>insOpts||(insOpts=Object.entries(PBC.INS).filter(([k,v])=>!['pipe','reed','brass','organ'].includes(v[3])&&!/harm|sax|tpt|tbn|horn|tuba|oboe|clarinet|bassoon|flute|fl_|picc|rec_|recorder|ocarina|bsn|ob_|cl_|wartuba|mtg_/.test(k)).sort((a,b)=>a[1][0].localeCompare(b[1][0])));
const prev={src:null,role:null,buf:null,t0:0,key:'',raf:0};
function stopPrev(){if(prev.src){try{prev.src.stop()}catch{}prev.src=null}cancelAnimationFrame(prev.raf);if(prev.ui)prev.ui.btn.textContent='Play instrument';prev.role=null}
async function playPrev(t,role,ui,at=0){stopPrev();ui.btn.textContent='Rendering…';prev.ui=ui;const key=JSON.stringify([t.id,t.rev,role,t.edit]);let buf=prev.key===key?prev.buf:null;
 if(!buf){try{const r=await PBC.render({seed:t.seed,genre:t.style,blend:t.blend,source:'library',faith:t.faith??s.src/100,avoid:s.usedPieces,L:t.L,offset:null,A:t.A,ctx,piece:t.piece||undefined,ch:t.edit,song:t.songEdit||t.song||null,solo:role});buf=r.buffer;prev.buf=buf;prev.key=key}catch(e){ui.btn.textContent='Play instrument';setStatus('Preview failed: '+e.message);return}}
 drawStem(ui.cv,buf);try{ctx.resume()}catch{}const src=ctx.createBufferSource();src.buffer=buf;src.loop=ui.rep.checked;src.connect(ctx.destination);src.start(0,at%buf.duration);prev.src=src;prev.role=role;prev.tid=t.id;prev.ui=ui;prev.t0=ctx.currentTime-at;ui.btn.textContent='Stop instrument';
 src.onended=()=>{if(prev.src===src)stopPrev()};const tick=()=>{if(prev.src!==src)return;const u=prev.ui;let p=ctx.currentTime-prev.t0;if(src.loop)p%=buf.duration;u.pos.textContent=p.toFixed(1)+' / '+buf.duration.toFixed(1)+'s';u.cur.style.left=Math.min(100,p/buf.duration*100)+'%';prev.raf=requestAnimationFrame(tick)};tick()}
function drawStem(cv,buf){const w=cv.width=cv.clientWidth*devicePixelRatio||1200,h=cv.height=90*devicePixelRatio,g=cv.getContext('2d'),a=buf.getChannelData(0),b=buf.getChannelData(1),n=a.length,step=Math.max(1,Math.floor(n/w));g.clearRect(0,0,w,h);g.fillStyle='#1c78c8';let mx=1e-4;const pk=new Float32Array(w);for(let x=0;x<w;x++){let m=0;for(let i=x*step;i<Math.min(n,(x+1)*step);i+=4){const v=Math.max(Math.abs(a[i]),Math.abs(b[i]));if(v>m)m=v}pk[x]=m;if(m>mx)mx=m}for(let x=0;x<w;x++){const y=pk[x]/mx*h*.46;g.fillRect(x,h/2-y,1,Math.max(1,2*y))}}

const KEYN=['C','D♭','D','E♭','E','F','F♯','G','A♭','A','B♭','B'],MODES={maj:'major',min:'minor',dor:'Dorian',mix:'Mixolydian',lyd:'Lydian'};
const SONGF=[['bpm','Tempo',60,180,.5,v=>v+' BPM'],['sw','Swing',0,.7,.01,v=>Math.round(v*100)+'%'],['gvar','Groove variation',0,1,.05,v=>Math.round(v*100)+'%'],['pump','Sidechain pump',0,.85,.01,v=>Math.round(v*100)+'%'],['H','Master'],['low','Low · 110 Hz',-12,12,.5,v=>v+' dB'],['lowmid','Low-mid · 450 Hz',-12,12,.5,v=>v+' dB'],['mid','Mid · 1.5 kHz',-12,12,.5,v=>v+' dB'],['presence','Presence · 4 kHz',-12,12,.5,v=>v+' dB'],['high','High · 9 kHz',-12,12,.5,v=>v+' dB'],['air','Air · 11 kHz shelf',0,6,.1,v=>v+' dB'],['width','Stereo width',.6,1.6,.01,v=>Math.round(v*100)+'%'],['warmth','Warmth (tape saturation)',0,.5,.01,v=>Math.round(v*200)+'%'],['glue','Glue compression',0,1,.01,v=>Math.round(v*100)+'%'],['loud','Loudness',-20,-9,.5,v=>v+' dB RMS'],['midDip','Midrange dip · 500 Hz–3 kHz',0,12,.5,v=>v==0?'Off':'−'+v+' dB'],['monoHz','Mono bass below',0,250,5,v=>v==0?'Off':v+' Hz'],['subHz','Remove rumble below',0,60,2,v=>v==0?'Off':v+' Hz'],['pocket','Voice pocket depth',0,2,.05,v=>Math.round(v*100)+'%'],['endCap','Ending can rise by',0,10,.5,v=>'+'+v+' dB'],['vWeight','Loudness set by the voice section',0,1,.05,v=>Math.round(v*100)+'%'],['H','Variety'],['variety','Variety per bed · harmony, patterns, tempo, mix',0,2,.05,v=>v==0?'Off · strict genre':v<.6?'Subtle':v<1.3?'Normal':'Wide'],['H','Blend'],['blendStyle','Blend style · dominant ↔ wild crossings',0,1,.05,v=>v<=.15?'Stay on the top genre':v<.45?'Mostly the top genre':v<.75?'Balanced crossings':'Wild crossings'],['H','Feel & space'],['expr','Expression (swells, vibrato, slides)',0,2,.05,v=>Math.round(v*100)+'%'],['art','Switch articulations (staccato / vibrato samples)',0,1,1,v=>v>=.5?'On':'Off'],['feel','Human feel (phrasing, groove)',0,2,.05,v=>Math.round(v*100)+'%'],['depth','Stage depth',0,2,.05,v=>Math.round(v*100)+'%'],['hrtf','Headphone surround (3D)',0,1,1,v=>v>=.5?'On':'Off'],['H','Arrangement'],['maxParts','Most parts at once',3,9,1,v=>v+' parts'],['thin','Thin counter/double under voice',0,1,1,v=>v>=.5?'On':'Off'],['tame','Lower shrill sustained sounds',0,1,1,v=>v>=.5?'On':'Off'],['tameAt','Shrill-note ceiling shift',-12,12,1,v=>v==0?'Default':(v>0?'+':'')+v+' semitones'],['harm','Fix clashing notes',0,1,1,v=>v>=.5?'On':'Off'],['rr','Vary repeated notes',0,1,1,v=>v>=.5?'On':'Off'],['drift','Synth analog drift',0,10,.2,v=>v==0?'Off':v+' cents']];
function songPanel(t){if(!t.songEdit)t.songEdit=JSON.parse(JSON.stringify(t.songDef));const e=t.songEdit,d=document.createElement('details');d.className='channel';d.open=t.openRole==='song';d.ontoggle=()=>{if(d.open)t.openRole='song'};const sm=document.createElement('summary');sm.textContent='Song · '+KEYN[e.key]+' '+(MODES[e.mode]||e.mode)+' · '+e.bpm+' BPM';d.append(sm);
 const p=document.createElement('p');p.className='mini';p.textContent='Key and mode were matched to the selected read; changing them can put the music against the voice. Tempo stays locked to the read’s timing only near the chosen value.';d.append(p);
 const ff=document.createElement('div');ff.className='fxFields';const sel=(name,opts,val,on)=>{const l=document.createElement('label');l.textContent=name;const s2=document.createElement('select');for(const[v,txt]of opts){const o=document.createElement('option');o.value=v;o.textContent=txt;if(String(v)===String(val))o.selected=true;s2.append(o)}s2.onchange=()=>on(s2.value);l.append(s2);ff.append(l)};
 sel('Key',KEYN.map((n,i)=>[i,n+(i===t.songDef.key?' (matched)':'')]),e.key,v=>{e.key=+v});
 sel('Mode',Object.entries(MODES).map(([k,v])=>[k,v+(k===t.songDef.mode?' (matched)':'')]),e.mode,v=>{e.mode=v});
 sel('Groove',[['none','No drums'],...PBC.grooves.map(g=>[g,g])],e.groove,v=>{e.groove=v});
 sel('Drum kit',PBC.kits.map(k=>[k,k]),e.kit,v=>{e.kit=v});
 for(const[k,name,mn,mx,st,fmt2]of SONGF){if(k=='H'){const hd=document.createElement('div');hd.className='fxHead';hd.textContent=name;ff.append(hd);continue}const l=document.createElement('label'),sp=document.createElement('span'),out=document.createElement('output');sp.textContent=name;out.textContent=fmt2(e[k]);sp.append(out);const r=document.createElement('input');r.type='range';r.min=mn;r.max=mx;r.step=st;r.value=e[k];r.oninput=()=>{e[k]=+r.value;out.textContent=fmt2(e[k])};l.append(sp,r);ff.append(l)}
 d.append(ff);return d}
function fxEditor(t){if(!t.edit)t.edit=JSON.parse(JSON.stringify(t.chan));const box=document.createElement('div');box.className='instrumentEditor';
 box.innerHTML='<p class="mini">Every part starts from the settings the composer chose. Open one to audition it on its own; the preview follows your edits. Apply changes re-renders the whole bed (same piece, same read) and updates the export.</p>';
 const acts=document.createElement('div');acts.className='editorActions';const ap=document.createElement('button');ap.className='primary';ap.textContent='Apply changes';const rs=document.createElement('button');rs.className='pill';rs.textContent='Reset instruments & effects';const msg=document.createElement('span');msg.className='mini';acts.append(ap,rs,msg);box.append(acts);
 ap.onclick=()=>{stopPrev();t.ch=JSON.parse(JSON.stringify(t.edit));t.song=t.songEdit?JSON.parse(JSON.stringify(t.songEdit)):t.song;msg.textContent='Re-rendering the bed…';s.queue.unshift(t);s.total++;work()};
 rs.onclick=()=>{stopPrev();t.ch=null;t.edit=null;t.song=null;t.songEdit=null;msg.textContent='Restoring the composer\'s settings…';s.queue.unshift(t);s.total++;work()};
 if(t.songDef)box.append(songPanel(t));
 const roles=Object.keys(t.edit).sort((a,b)=>Object.keys(ROLEN).indexOf(a)-Object.keys(ROLEN).indexOf(b));
 for(const role of roles){const e=t.edit[role],d=document.createElement('details');d.className='channel';if(t.openRole===role)d.open=true;d.ontoggle=()=>{if(d.open)t.openRole=role};const sm=document.createElement('summary');const lab=()=>(ROLEN[role]||role)+' · '+(e.id?PBC.INS[e.id][0]:'Drum kit');sm.textContent=lab();d.append(sm);
  const pv=document.createElement('div');pv.className='stemPreview';pv.innerHTML='<div class="stemControls"><button class="pill">Play instrument</button><label><input type="checkbox"> Repeat</label><span class="mini">0.0 / '+(t.L||0).toFixed(1)+'s</span></div><div class="stemWave"><canvas></canvas><span class="stemCursor"></span></div>';d.append(pv);
  const ui={btn:pv.querySelector('button'),rep:pv.querySelector('input'),pos:pv.querySelector('.mini'),cv:pv.querySelector('canvas'),cur:pv.querySelector('.stemCursor')};if(prev.src&&prev.role===role&&prev.tid===t.id){prev.ui=ui;ui.btn.textContent='Stop instrument';ui.rep.checked=!!prev.src.loop;if(prev.buf)requestAnimationFrame(()=>drawStem(ui.cv,prev.buf))}ui.btn.onclick=()=>{if(prev.role===role&&prev.src)stopPrev();else playPrev(t,role,ui)};ui.rep.onchange=()=>{if(prev.src&&prev.role===role)prev.src.loop=ui.rep.checked};
  let deb=0;const changed=()=>{if(prev.role===role&&prev.src){clearTimeout(deb);deb=setTimeout(()=>{const at=ctx.currentTime-prev.t0;playPrev(t,role,ui,at)},700)}};
  const tg=document.createElement('div');tg.className='channelToggles';tg.innerHTML='<label><input type="checkbox"'+(e.mute?' checked':'')+'> Mute</label>';tg.querySelector('input').onchange=ev=>{e.mute=ev.target.checked};d.append(tg);
  const ff=document.createElement('div');ff.className='fxFields';
  if(e.id){const l=document.createElement('label');l.textContent='Instrument';const sel=document.createElement('select');for(const[k,v]of insList()){const o=document.createElement('option');o.value=k;o.textContent=v[0];if(k===e.id)o.selected=true;sel.append(o)}sel.onchange=()=>{e.id=sel.value;sm.textContent=lab();changed()};l.append(sel);ff.append(l)}
  for(const[k,name,mn,mx,st,fmt2]of FXF){if(e[k]===undefined)continue;if(k=='jit'){const hd=document.createElement('div');hd.className='fxHead';hd.textContent='Human feel';ff.append(hd)}const l=document.createElement('label');if(k=='space'){l.textContent=name;const sel=document.createElement('select');for(const v of['room','hall','plate','spring','chamber','gated']){const o=document.createElement('option');o.value=v;o.textContent=v;if(v===e.space)o.selected=true;sel.append(o)}sel.onchange=()=>{e.space=sel.value;changed()};l.append(sel);ff.append(l);continue}
   const sp=document.createElement('span'),out=document.createElement('output');sp.textContent=name;out.textContent=fmt2(e[k]);sp.append(out);const r=document.createElement('input');r.type='range';r.min=mn;r.max=mx;r.step=st;r.value=e[k];r.oninput=()=>{e[k]=+r.value;out.textContent=fmt2(e[k])};r.onchange=changed;l.append(sp,r);ff.append(l)}
  d.append(ff);box.append(d)}
 return box}
"""
rep("$('compose').onclick=()=>composeNew(8);",JS+"$('compose').onclick=()=>composeNew(8);")
CSS=".instrumentEditor{border-top:1px solid #e3eaf0;margin-top:10px;padding-top:10px}.instrumentEditor .mini{font-size:12px;color:#5d7184}.editorActions{display:flex;gap:8px;align-items:center;margin:8px 0;flex-wrap:wrap}.channel{border-top:1px solid #e9eef3;padding:10px 0}.channel summary{font-weight:700;cursor:pointer;font-size:14px}.stemControls{display:flex;gap:12px;align-items:center;margin:10px 0}.stemWave{position:relative;height:90px;background:#eef4f9;border:1px solid #dde7ef;border-radius:8px;overflow:hidden}.stemWave canvas{width:100%;height:90px;display:block}.stemCursor{position:absolute;top:0;bottom:0;width:2px;background:#d8742a;left:0}.channelToggles{display:flex;gap:16px;margin:8px 0;font-size:13px}.fxFields{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px 18px}.fxFields label{display:flex;flex-direction:column;gap:6px;font-size:12.5px;color:#3d5265}.fxFields label span{display:flex;justify-content:space-between}.fxFields select{padding:6px;border:1px solid #d3dee8;border-radius:7px;background:#fff}.fxFields input[type=range]{width:100%}.fxHead{grid-column:1/-1;font-weight:700;font-size:12.5px;color:#22405a;margin-top:6px;border-top:1px dashed #dbe5ee;padding-top:8px}.pill.on{background:#e8f1fb;border-color:#9cc3ea}"
rep("</style>",CSS+"</style>")
